    detailed: [["span 1", "10px"], ["span 1", "10px"], ["span 1", "10px"], ["span 1", "10px"], ["span 2", "14px"], ["span 2", "14px"], ["span 1", "12px"], ["span 1", "12px"], ["span 1", "12px"], ["span 1", "12px"]],
