    // Срок уже вышел — поле пустое: продлевать или снимать, решает человек, а не значение по умолчанию.
    const left = user.expires ? daysLeft(user.expires) : 0;
    const cur = !user.expires ? "" : (Number.isFinite(left) && left > 0 ? String(left) : "");
    let val = cur;
    const until = el("span", { class: "gx-fieldbtn__v gx-num" });
    // Срок на сервере — «сейчас + N дней» (_users_set_expiry_locked), и дата здесь та же: прежнее «+ N − 1» показывало
