    const dField = U.field(t("udDaysL"), input, { hint: "" });
    const chips = quickChips([[7, "7"], [30, "30"], [90, "90"], [0, t("udNoExpiry")]], () => norm() ?? "", (v) => { val = v === "0" ? "" : v; input.value = val; countHint(dField, input, { v: val }); syncUntil(); });
    const syncChips = () => chips.querySelectorAll("button").forEach((b, i) => b.setAttribute("aria-pressed", String(String([7, 30, 90, 0][i]) === norm())));
    syncUntil();
