    const dis443 = siteMode || !!heldBy;
    const f = { port: prev.port || "auto", cport: prev.cport || "", preset: prev.preset || "default", subnet: prev.subnet || "" };
    if (dis443 && f.port === "443") f.port = "auto";
    const err = prev.err || null;
