  const prNow = (label, value) => el("div", { class: "gx-field" }, el("span", { class: "gx-field__l", text: label }), el("div", { class: "gx-ro", text: value }));
  // Перенос порта у профиля, подхваченного у приложения: люди без ключа на сервере останутся без связи — только словом.
