    if (!force && sig === bkSig && sec.childNodes.length) return;
    bkSig = sig;
    sec.innerHTML = "";
    const createBtn = U.btn(bk.creating ? t("bkCreating") : t("bkCreate"), "primary", () => bkCreate(),
      { icon: bk.creating ? "arrow-rotate-right" : "plus", spin: bk.creating, md: true, dis: bk.creating || !hasAction("backup-create") });
    // Что сломано — сверху, отдельными карточками: ручная копия не удалась, ночной проход закончился отказом.
    const top = [];
    if (bk.fail) {
      top.push(U.al("danger", bk.fail.low ? `${t("bkFailB")} ${t("bkLowDisk")}.` : t("bkFailPlain"), `${bk.fail.text} ${bk.fail.low ? t("bkFailLow") : t("bkFailAny")}`.trim(),
        { card: true, btns: [U.btn(t("bkRetry"), "inverse", () => bkCreate(), { icon: "arrow-rotate-right" }), bk.fail.low ? U.btn(t("bkToLogs"), "ghost", () => setPage("logs")) : null] }));
    }
    const last = state.backupLast || null;
    if (last && last.tick_ok === false) {
      const r = bkLowDisk(last.tick_code) ? t("bkLowDisk") : (last.tick_code || "?");
      top.push(U.al("danger", tf("bkNightB", { r }), tf("bkNightT", { t: fmtDate(last.tick_at), last: last.created ? tf("bkNightLast", { t: fmtDate(last.created) }) : t("bkNightNone") }),
        { card: true, btns: [U.btn(t("bkNightNow"), "inverse", () => bkCreate(), { icon: "plus" })] }));
    }
    if (state.backupsErr) {
      top.push(U.al("danger", t("bkLoadErrB"), state.backupsErr, { card: true, btns: [U.btn(t("uRetry"), "inverse", () => refreshPage().catch(showError), { icon: "arrow-rotate-right" })] }));
    }
    if (top.length) sec.append(U.row([U.plain(top)], { full: true }));
    if (!d) {
      if (!state.backupsErr) sec.append(U.row([U.sec(t("bkTitle"), t("bkDesc"), [U.skel(6)], { icon: "database" })], { full: true }));
      return;
    }
