    const sig = JSON.stringify([state.lang, isPhone(), sg.tab, sg.err, state.settings, sg.status, sg.pf, sg.pfBusy, sg.pfErr, sg.sc, sg.scBusy, sg.scErr, sg.mini,
      sg.mirror, sg.mirrorErr, sg.clients, !!sg.tplCats, state.template, sg.dns && sg.dns.sel, sg.ep && sg.ep.sel, sg.langDraft, sg.tab === "look" ? look : 0,
      state.actions ? 1 : 0, (state.overview || {}).edge ? 1 : 0]);
    if (!force && sig === sgSig && sec.childNodes.length) return;
    sgSig = sig;
    // Перерисовка не сбивает ввод: поле с фокусом и курсором возвращаются на место.
    const act = document.activeElement;
    const keep = act && act.id && sec.contains(act) ? { id: act.id, s: act.selectionStart, e: act.selectionEnd } : null;
    sec.innerHTML = "";
    sec.append(sgTabsRow());
