      const n = document.getElementById(keep.id);
      if (n) { n.focus({ preventScroll: true }); try { if (keep.s !== null && keep.s !== undefined) n.setSelectionRange(keep.s, keep.e); } catch (e) { /* не текстовое поле */ } }
